import org.junit.*;
import org.junit.Test;
import org.mockito.ArgumentMatchers;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class PrototypeObjectType_matchConstraint_TriageGen0Test {

    @Test
    public void testMatchConstraint_HasReferenceName_ReturnsEarly() {
        // Arrange
        PrototypeObjectType prototypeObjectType = mock(PrototypeObjectType.class);
        JSType constraint = mock(JSType.class);

        // Setup: hasReferenceName() returns true, so the method should return immediately
        when(prototypeObjectType.hasReferenceName()).thenReturn(true);

        // Act
        prototypeObjectType.matchConstraint(constraint);

        // Assert: Verify that no further interactions occur (specifically no record type check)
        verify(prototypeObjectType, ArgumentMatchers.never()).matchRecordTypeConstraint(ArgumentMatchers.any());
    }

    @Test
    public void testMatchConstraint_NoReferenceName_NotRecordType_DoesNothing() {
        // Arrange
        PrototypeObjectType prototypeObjectType = mock(PrototypeObjectType.class);
        JSType constraint = mock(JSType.class);

        // Setup: hasReferenceName() is false, isRecordType() is false
        when(prototypeObjectType.hasReferenceName()).thenReturn(false);
        when(constraint.isRecordType()).thenReturn(false);

        // Act
        prototypeObjectType.matchConstraint(constraint);

        // Assert: Verify matchRecordTypeConstraint was never called
        verify(prototypeObjectType, ArgumentMatchers.never()).matchRecordTypeConstraint(ArgumentMatchers.any());
    }

    @Test
    public void testMatchConstraint_NoReferenceName_IsRecordType_CallsMatchRecordTypeConstraint() {
        // Arrange
        PrototypeObjectType prototypeObjectType = mock(PrototypeObjectType.class);
        JSType constraint = mock(JSType.class);
        ObjectType constraintObjectType = mock(ObjectType.class);

        // Setup: hasReferenceName() is false, isRecordType() is true
        when(prototypeObjectType.hasReferenceName()).thenReturn(false);
        when(constraint.isRecordType()).thenReturn(true);
        when(constraint.toObjectType()).thenReturn(constraintObjectType);

        // Act
        prototypeObjectType.matchConstraint(constraint);

        // Assert: Verify that matchRecordTypeConstraint is called with the object type from the constraint
        verify(prototypeObjectType).matchRecordTypeConstraint(constraintObjectType);
    }
}
